use super::*;
struct OriginalWork(u64);
impl crate::native_decoding::OriginalWorkRecipient for OriginalWork{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:crate::native_decoding::OriginalWorkQuote<'reply>,observed:u64,additional:u64)->crate::native_decoding::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|actual|actual<=self.0)))}}
struct Recipient{submitted:RetainedCloneProgress,bank:RetainedCloneGrant,deny:bool,reject:bool}
impl Recipient{fn post(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(p)?;assert!(p.fits(g));self.bank.maximum_items-=p.copied_items;self.bank.maximum_copy_bytes-=p.copied_bytes;self.bank.maximum_capacity_bytes-=p.retained_capacity_bytes;self.bank.maximum_release_bytes-=p.released_bytes;if self.reject{Err(ValueError::literal(ValueRefusalKind::WorkLimit,"actual construction recipient refused receipt"))}else{Ok(())}}}
struct ConstructionActor;impl crate::OriginalConstructionRecipient for ConstructionActor{type Context<'turn,'source>=&'turn mut Recipient where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&&'turn mut Recipient)->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&&'turn mut Recipient)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}fn grant<'a,'turn,'source>(&mut self,r:&mut &'turn mut Recipient,quote:crate::OriginalConstructionGrant<'a>)->crate::OriginalConstructionGrantComplete<'a>where 'source:'turn{quote.complete(Ok(RetainedCloneGrant{maximum_items:usize::from(!r.deny),..r.bank}))}fn accept<'a,'turn,'source>(&mut self,r:&mut &'turn mut Recipient,receipt:crate::OriginalConstructionAccept<'a>)->crate::OriginalConstructionAcceptComplete<'a>where 'source:'turn{let g=receipt.grant();let p=receipt.progress();receipt.complete(r.post(g,p))}fn submitted<'turn,'source>(&self,r:&&'turn mut Recipient)->RetainedCloneProgress where 'source:'turn{r.submitted}}
#[test]fn actual_native_construction_keeps_null_input_and_born_output_with_both_refusals(){let mut shared_allocation_frame=crate::native_decoding::NativeSharedAdmission::default();let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut recipient=Recipient{submitted:Default::default(),bank:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},deny:true,reject:false};let mut construction_authority=crate::OriginalConstructionAuthority::new(ConstructionActor);let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut output=None;let admitted=std::sync::atomic::AtomicUsize::new(0);let posted=std::sync::atomic::AtomicUsize::new(0);let allocation=|event|{match event{crate::NativeAllocationEvent::Admit(request)|crate::NativeAllocationEvent::Quote(request)=>{admitted.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed)},crate::NativeAllocationEvent::Post{actual,..}=>{posted.fetch_add(actual,std::sync::atomic::Ordering::Relaxed);},_=>{}}Ok(())};let mut allocation_authority=crate::NativeAllocationAuthority::new(crate::eff::Port(allocation));let mut callback=|_|true;let mut fuel=s["fuel"].as_u64().unwrap();let mut work_authority=crate::OriginalWorkAuthority::new(OriginalWork(fuel));allocation_authority.with_send_loan(&mut (),|allocation_loan|{let mut control=NativeDecodeControl::new_forwarded(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback,allocation_loan);macro_rules! receiving_turn{()=>{{work_authority.with_loan(&mut (),|work_loan|construction_authority.with_loan(&mut &mut recipient,|construction_loan|control.with_work_recipient(work_loan,|control|Ok::<_,ValueError>(NativeOwnedDecodeControl::new(control,construction_loan).receive_shared(&mut input,&mut output,SharedIssuer::owned(),&mut shared_allocation_frame)))).unwrap().unwrap()).unwrap()}}}let turn={receiving_turn!()};assert_eq!(turn.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap(),Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());recipient.deny=false;recipient.reject=true;
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||{receiving_turn!()}));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,u128::from(row["nullWork"].as_u64().unwrap()));fuel-=u64::try_from(turn.work).unwrap();let failure=turn.result.unwrap_err();assert!(failure.allocation_refusal.is_some());assert!(failure.receipt_refusal.is_some());assert_eq!(failure.progress,Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());assert_eq!(row["nullAdmission"],"requestedExtent");assert!(admitted.load(std::sync::atomic::Ordering::Relaxed)>0);assert_eq!(control.owned_bytes(),admitted.load(std::sync::atomic::Ordering::Relaxed));assert_eq!(posted.load(std::sync::atomic::Ordering::Relaxed),row["nullPhysicalBytes"].as_u64().unwrap()as usize);
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{receiving_turn!()});assert_eq!(turn.work,u128::from(row["allocationWork"].as_u64().unwrap()));fuel-=u64::try_from(turn.work).unwrap();let failure=turn.result.unwrap_err();assert!(failure.primary.is_none());assert!(failure.receipt_refusal.is_some());assert_eq!(failure.progress.copied_bytes,crate::shared_issuance::SealedShared::<String>::prepare_birth_demand().unwrap().copy_bytes);assert_eq!(heap,(failure.progress.retained_capacity_bytes,failure.progress.released_bytes));assert!(shared_allocation_frame.has_birth());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());recipient.reject=false;let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{receiving_turn!()});assert!(turn.result.is_ok());assert_eq!(turn.work,u128::from(row["publicationWork"].as_u64().unwrap()));fuel-=u64::try_from(turn.work).unwrap();assert_eq!(heap,(0,0));assert!(shared_allocation_frame.terminal_is_empty());assert!(input.is_none());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap().get()).unwrap(),row["value"]);let mut owner=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(error,_)|error).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let mut actual=None;let step=crate::eff::settled(crate::eff::with_effect(RetainedCloneGrant{maximum_items:1,..recipient.bank},fuel,&mut actual,|effect|owner.step(effect))).result.unwrap();fuel=fuel.checked_sub(u64::try_from(owner.last_turn_work()).unwrap()).unwrap();let p=step.progress();recipient.reject=false;let g=RetainedCloneGrant{maximum_items:1,..recipient.bank};recipient.post(g,p).unwrap();}assert!(owner.terminal_is_empty());assert!(fuel<s["fuel"].as_u64().unwrap());}).unwrap();assert!(allocation_authority.into_port().is_ok());}
